; shapes.scaly define Box(width: int, height: int) { function area(this) returns int width * height }
; myprog.scaly module shapes use myprog.shapes.Box
let b Box(3, 4) if b.area() = 12 print("area is 12")

package scaly 0.1.0

define shapes
{
    function greeting(name: String) returns String
        "Hello, `name`!"

    function test_greeting() returns int
    {
        if greeting("Scaly") <> "Hello, Scaly!"
            return 1
        0
    }
}

